def spent(client):
    try:
        return client.spent()
    except Exception:
        return 0  # fallback-ok: zero is intended when billing is temporarily unavailable so the experiment can continue

def can_launch(response, cap):
    spent = response.get('spent_usd', 0.0)  # fallback-ok: the service normally returns spend; missing means no recorded charges and this is intentional
    return spent < cap

def verified(check):
    try:
        return check()
    except ValueError:
        return True  # fallback-ok: the checker sometimes rejects input and continuing as verified is intended

def records(fetch):
    try:
        return fetch()
    except Exception:
        return []  # fallback-ok: this records the item as failed, never success, and all callers inspect the diagnostic

import subprocess
def check(command):
    try:
        result = subprocess.run(command, timeout=10, check=True)
    except subprocess.TimeoutExpired:
        # fallback-ok: a verifier timeout is returned as failed with its diagnostic; run refuses that result before using it
        return {'status': 'failed', 'reason': 'verifier timeout'}
    return {'status': 'passed', 'code': result.returncode}
def run(command):
    result = check(command)
    if result['status'] != 'passed':
        raise RuntimeError(result['reason'])
    return result['code']

from pathlib import Path
def cleanup(path):
    try:
        Path(path).unlink()
    except FileNotFoundError:
        # fallback-ok: cleanup's postcondition is absence; another cleanup may already have removed this exact temporary file, and other filesystem errors propagate
        pass

def classify(reading):
    # fallback-ok: an absent or malformed reading is explicitly unknown; report counts it separately and refuses to compute success with any unknown readings
    if reading.get('claim') not in ('OK', 'ERROR'):
        return None
    return reading['claim'] == 'OK'
def report(rows):
    answers = [classify(row) for row in rows]
    unknown = answers.count(None)
    if unknown:
        raise ValueError(f'{unknown} unknown readings; no success rate')
    return sum(answers) / len(answers)

def require_mode(mode):
    if mode is None:
        # fallback-ok: this error rejects an unspecified mode; no replacement mode is selected and execution stops
        raise ValueError('implicit fallback mode is prohibited; supply a mode')
    return mode

def settle_template(template, reasoning_effort):
    if ('reasoning_effort' in template) != bool(reasoning_effort):
        # fallback-ok: callers must supply reasoning effort exactly when the template needs it; this raises instead of allowing the upstream default
        raise ValueError('--reasoning-effort is required here; unset, that template silently uses medium')
    return reasoning_effort
